package mx.taller.auth;
import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/usuarios") public class UsuarioController {
 private final UsuarioRepository repo; public UsuarioController(UsuarioRepository repo){this.repo=repo;}
 @GetMapping @PreAuthorize("hasRole('ADMINISTRADOR_TALLER')") public org.springframework.data.domain.Page<Map<String,Object>> listar(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size,@RequestParam(defaultValue="email") String sort,@RequestParam(defaultValue="asc") String dir){if(!Set.of("email","rol").contains(sort))sort="email";var pageable=org.springframework.data.domain.PageRequest.of(Math.max(0,page),Math.min(10,Math.max(1,size)),org.springframework.data.domain.Sort.by("desc".equalsIgnoreCase(dir)?org.springframework.data.domain.Sort.Direction.DESC:org.springframework.data.domain.Sort.Direction.ASC,sort));return repo.findByActivoTrue(pageable).map(u->{Map<String,Object> m=new HashMap<>();m.put("id",u.getId());m.put("email",u.getEmail());m.put("rol",u.getRol()==null?"PENDIENTE":u.getRol().name());return m;});}
 @GetMapping("/pendientes") @PreAuthorize("hasRole('ADMINISTRADOR_TALLER')") public List<Map<String,Object>> pendientes(){return repo.findByRolIsNullAndActivoTrue().stream().map(u->Map.<String,Object>of("id",u.getId(),"email",u.getEmail())).toList();}
 @PatchMapping("/{id}/rol") @PreAuthorize("hasRole('ADMINISTRADOR_TALLER')") public Map<String,String> asignar(@PathVariable UUID id,@jakarta.validation.Valid @RequestBody AsignacionRolDto dto){Usuario u=repo.findById(id).filter(Usuario::isActivo).orElseThrow(()->new IllegalArgumentException("Usuario no encontrado"));u.setRol(dto.rol());repo.save(u);return Map.of("mensaje","Rol asignado");}
 @DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMINISTRADOR_TALLER')") public Map<String,String> desactivar(@PathVariable UUID id){Usuario u=repo.findById(id).filter(Usuario::isActivo).orElseThrow(()->new IllegalArgumentException("Usuario no encontrado"));u.setActivo(false);repo.save(u);return Map.of("mensaje","Usuario desactivado");}
 public record AsignacionRolDto(@jakarta.validation.constraints.NotNull Rol rol){}
}
